def family_init(ctx):
    bars = ctx.bars
    n = len(bars)
    c = [float(b["c"]) for b in bars]
    v = [float(b.get("v") or 0.0) for b in bars]

    W = int(ctx.p.av_win)
    S = int(ctx.p.sig_win)

    r = [0.0] * n
    for t in range(1, n):
        r[t] = (c[t] / c[t - 1] - 1.0) if c[t - 1] > 0.0 else 0.0
    ctx.r = r

    av = [None] * n
    run = 0.0
    for t in range(n):
        if t >= 1:
            run += v[t - 1]
            if t - 1 - W >= 0:
                run -= v[t - 1 - W]
            if t >= W:
                mean = run / W
                if mean > 0.0:
                    av[t] = v[t] / mean
    ctx.av = av

    sd = [None] * n
    s1 = 0.0
    s2 = 0.0
    for t in range(n):
        if t >= 1:
            s1 += r[t - 1]
            s2 += r[t - 1] * r[t - 1]
            if t - 1 - S >= 0:
                o = r[t - 1 - S]
                s1 -= o
                s2 -= o * o
            if t >= S:
                mu = s1 / S
                var = s2 / S - mu * mu
                if var > 1e-18:
                    sd[t] = var ** 0.5
    ctx.sd = sd
    ctx.start = max(W, S) + 2


def signal(ctx, i):
    if i < ctx.start:
        return 0
    a = ctx.av[i]
    s = ctx.sd[i]
    if a is None or s is None or s <= 0.0:
        return 0
    if a >= float(ctx.p.av_min) and abs(ctx.r[i]) >= float(ctx.p.ret_sig) * s:
        return -1
    return 0


def exit_signal(ctx, i):
    a = ctx.av[i]
    if a is None:
        return False
    return a < float(ctx.p.av_out)
